argv:
$ErrorActionPreference='Stop'
$root='E:\WebAIBridge-R68-OBSERVABILITY-20261014-GPT6'
$sha='01893cd6d729aa3c4779298c42553c5e9f9170f2'
if(@(& git.exe -C $root status --porcelain=v1 --untracked-files=no).Count -ne 0){throw 'ISOLATED_TREE_DIRTY'}
& git.exe -C $root fetch --quiet --no-tags origin agent/r68-live-chat-observability-20261014
if($LASTEXITCODE -ne 0){throw 'FETCH_FAIL'}
& git.exe -C $root checkout --quiet --detach $sha
if($LASTEXITCODE -ne 0){throw 'CHECKOUT_FAIL'}
if(([string](& git.exe -C $root rev-parse HEAD)).Trim() -ne $sha){throw 'SHA_MISMATCH'}
$log=Join-Path $root 'R68_SIDECAR_TESTS.txt'
Push-Location (Join-Path $root 'app')
try{
 & node.exe --test r68-live-chat-observability.test.js r68-live-viewer.test.js autonomous-send-gate-r50.test.js r65-global-canary-cap.test.js *> $log
 $rc=$LASTEXITCODE
 & node.exe --check r68-live-viewer.js
 $checkRc=$LASTEXITCODE
 $html=Get-Content -LiteralPath 'r68-live-viewer.html' -Raw
 $match=[regex]::Match($html,'(?s)<script>(.*?)</script>')
 if(-not $match.Success){throw 'SIDECAR_INLINE_JS_MISSING'}
 $temp=Join-Path $root 'R68_SIDE_UI_SCRIPT_CHECK.js'
 [IO.File]::WriteAllText($temp,$match.Groups[1].Value,[Text.UTF8Encoding]::new($false))
 & node.exe --check $temp
 $uiRc=$LASTEXITCODE
}finally{Pop-Location}
Write-Output ('R68_SOURCE_SHA='+$sha)
Write-Output ('TEST_EXIT='+$rc)
Write-Output ('NODE_SOURCE_EXIT='+$checkRc)
Write-Output ('HTML_INLINE_JS_EXIT='+$uiRc)
Select-String -LiteralPath $log -Pattern '^ℹ (?:tests|pass|fail|skipped)|^✖'|Select-Object -Last 12|ForEach-Object{Write-Output $_.Line}
Write-Output ('PRODUCTION_HEAD='+(& git.exe -C 'E:\WebAIBridge' rev-parse HEAD))
if($rc -ne 0 -or $checkRc -ne 0 -or $uiRc -ne 0){throw 'R68_SIDECAR_VERIFICATION_FAILED'}
